[
  {
    "kind": "narration",
    "text": "Marlow and Wren approach Ash, who has been waiting patiently.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "472aa77b-f9c4-43e0-8c15-8d984ec6f368",
    "text": "\"Dawn bell means the first stalls are opening.\"",
    "cited_fact_keys": ["reaction:1"]
  },
  {
    "kind": "narration",
    "text": "Ash explains the significance of the dawn bell to Wren.",
    "cited_fact_keys": ["reaction:1"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "59c1ee2b-d9c6-4cff-ba3f-3833ef1eedfd",
    "text": "\"Aye, and mind the loose stones past the bridge.\"",
    "cited_fact_keys": ["reaction:2"]
  },
  {
    "kind": "narration",
    "text": "Marlow adds a warning about the path ahead.",
    "cited_fact_keys": ["reaction:2"]
  },
  {
    "kind": "narration",
    "text": "Marlow attempts to communicate with Ash about the clear road past the hearth.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "narration",
    "text": "Wren attempts to discuss the dawn patrol with Ash.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "narration",
    "text": "The three of them stand there, a mix of anticipation and caution in the air.",
    "cited_fact_keys": []
  }
]

[
  {
    "kind": "narration",
    "text": "Marlow and Wren attempt to communicate with Ash.",
    "cited_fact_keys": ["attempt:communicate"]
