  }
]

[
  {
    "kind": "narration",
    "text": "Wren tries to convey something to Ash, but Ash seems preoccupied.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "narration",
    "text": "Meanwhile, Marlow keeps a watchful eye on the surroundings.",
    "cited_fact_keys": ["attempt:observe"]
  },
  {
    "kind": "narration",
    "text": "Ash patiently awaits, his gaze fixed on the horizon.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "ae77b715-afab-4bcb-9953-a78693892f9a",
    "text": "Ash turns to Wren, \"Dawn bell means the market's waking.\"",
    "cited_fact_keys": ["reaction:1"]
  }
]

[
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash, eager to discuss their plans for the day.",
    "cited_fact_keys": ["attempt:communicate"],
    "speaker_id": null
  },
  {
    "kind": "narration",
    "text": "Ash, however, is preoccupied and waits for Wren to finish.",
    "cited_fact_keys": ["attempt:wait"],
    "speaker_id": null
  },
  {
    "kind": "dialogue",
    "text": "Ash turns to Wren, \"Dawn bell means the market is waking early today, so hurry down with coin and basket before the best bread and freshest fish are gone from the stalls.\"",
    "cited_fact_keys": ["reaction:1"],
    "speaker_id": "397a8531-8422-4822-aa41-63a4f42e3a62"
  }
]

[
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash, asking, 'Is the old bridge safe to cross?'",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "action",
    "text": "Ash waits for Wren's response.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "3755eb22-2db6-4d8b-bf0e-758c9fff24ab",
    "text": "\"No.\" Ash responds curtly.",
    "cited_fact_keys": ["reaction:1"]
  }
]

[
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash, asking, 'What news from the mill, Ash?'",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "action",
    "text": "Ash waits for Wren's response.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "text": "\"It's still standing, unless someone's moved it.\"",
    "cited_fact_keys": ["reaction:1"],
    "speaker_id": "e563640f-c8bc-45c3-a69d-7016b472984f"
  }
